// netlify/functions/hello.ts
import type { Handler, HandlerEvent, HandlerContext } from '@netlify/functions';

interface RequestBody {
  name?: string;
}

export const handler: Handler = async (
  event: HandlerEvent,
  _context: HandlerContext
) => {
  if (event.httpMethod !== 'POST') {
    return {
      statusCode: 405,
      body: JSON.stringify({ error: 'Method Not Allowed' }),
    };
  }

  const body: RequestBody = event.body ? JSON.parse(event.body) : {};
  const name = body.name ?? 'World';

  return {
    statusCode: 200,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ message: `Hello, ${name}!`, timestamp: Date.now() }),
  };
};

interface NetlifyBuild {
  id: string;
  deploy_id: string;
  done: boolean;
  error: string | null;
  created_at: string;
}

async function triggerNetlifyDeploy(
  siteId: string,
  authToken: string
): Promise<NetlifyBuild> {
  const response = await fetch(
    `https://api.netlify.com/api/v1/sites/${siteId}/builds`,
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${authToken}`,
        'Content-Type': 'application/json',
      },
    }
  );

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`Netlify deploy failed: ${response.status} ${errorText}`);
  }

  const build = (await response.json()) as NetlifyBuild;
  console.log(`Deploy triggered. Build ID: ${build.id}`);
  return build;
}

// Usage
await triggerNetlifyDeploy(
  process.env.NETLIFY_SITE_ID!,
  process.env.NETLIFY_AUTH_TOKEN!
);
